-- Default off: no activation row is inserted by migration.
CREATE TABLE IF NOT EXISTS continuous_undo_serialization_activation(singleton INTEGER PRIMARY KEY CHECK(singleton=1),activated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_update BEFORE UPDATE ON continuous_undo_serialization_activation BEGIN SELECT RAISE(ABORT,'undo serialization activation immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_delete BEFORE DELETE ON continuous_undo_serialization_activation BEGIN SELECT RAISE(ABORT,'undo serialization activation retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_replace BEFORE INSERT ON continuous_undo_serialization_activation WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=NEW.singleton) BEGIN SELECT RAISE(ABORT,'undo serialization activation collision'); END;
CREATE TABLE IF NOT EXISTS continuous_pending_undo(
 request_id TEXT PRIMARY KEY,
 expense_id TEXT NOT NULL,
 source_version INTEGER NOT NULL CHECK(source_version>0),
 publication_transition_id TEXT NOT NULL REFERENCES continuous_publication_intents(transition_id),
 line_user_id TEXT NOT NULL,
 trace_id TEXT NOT NULL,
 actor_employee_id TEXT,
 branch_id TEXT,
 state TEXT NOT NULL CHECK(state IN ('PENDING','APPLIED','REVIEW')),
 last_error TEXT,
 audit_id TEXT,
 cancelled_version INTEGER,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE(expense_id,source_version),
 CHECK((state='PENDING' AND last_error IS NULL AND audit_id IS NULL AND cancelled_version IS NULL) OR (state='REVIEW' AND last_error='DEFERRED_UNDO_APPLY_FAILED' AND audit_id IS NULL AND cancelled_version IS NULL) OR (state='APPLIED' AND last_error IS NULL AND audit_id IS NOT NULL AND cancelled_version>source_version))
);
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_insert BEFORE INSERT ON continuous_pending_undo
WHEN NEW.state<>'PENDING' OR NOT EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=1) OR NOT EXISTS(SELECT 1 FROM expense_events e JOIN continuous_publication_intents i ON i.transition_id=NEW.publication_transition_id AND i.entity_id=e.expense_id AND i.source_version=e.version AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE e.expense_id=NEW.expense_id AND e.version=NEW.source_version AND e.line_user_id=NEW.line_user_id AND e.status='CONFIRMED' AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW'))))
BEGIN SELECT RAISE(ABORT,'pending undo requires confirmed owner'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_transition BEFORE UPDATE ON continuous_pending_undo
WHEN NEW.request_id IS NOT OLD.request_id OR NEW.expense_id IS NOT OLD.expense_id OR NEW.source_version IS NOT OLD.source_version OR NEW.publication_transition_id IS NOT OLD.publication_transition_id OR NEW.line_user_id IS NOT OLD.line_user_id OR NEW.trace_id IS NOT OLD.trace_id OR NEW.actor_employee_id IS NOT OLD.actor_employee_id OR NEW.branch_id IS NOT OLD.branch_id OR NEW.created_at IS NOT OLD.created_at OR OLD.state<>'PENDING' OR NOT (NEW.state='REVIEW' AND NEW.last_error='DEFERRED_UNDO_APPLY_FAILED' AND NEW.audit_id IS NULL AND NEW.cancelled_version IS NULL OR NEW.state='APPLIED' AND NEW.last_error IS NULL AND EXISTS(SELECT 1 FROM expense_events e JOIN expense_audit_log a ON a.expense_id=e.expense_id AND a.audit_id=NEW.audit_id AND a.action='UNDO' JOIN continuous_pending_undo_apply_auth t ON t.request_id=OLD.request_id AND t.audit_id=a.audit_id WHERE e.expense_id=NEW.expense_id AND e.status='CANCELLED' AND e.version=NEW.cancelled_version AND json_extract(a.before_json,'$.version')=OLD.source_version AND json_extract(a.after_json,'$.version')=NEW.cancelled_version AND EXISTS(SELECT 1 FROM sync_jobs j WHERE j.entity_type='EXPENSE' AND j.entity_key=e.expense_id AND j.entity_version=e.version)))
BEGIN SELECT RAISE(ABORT,'pending undo transition unverified'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_no_delete BEFORE DELETE ON continuous_pending_undo BEGIN SELECT RAISE(ABORT,'pending undo retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_no_replace BEFORE INSERT ON continuous_pending_undo WHEN EXISTS(SELECT 1 FROM continuous_pending_undo WHERE request_id=NEW.request_id OR (expense_id=NEW.expense_id AND source_version=NEW.source_version)) BEGIN SELECT RAISE(ABORT,'pending undo collision'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_blocks_publish BEFORE INSERT ON continuous_publication_intents WHEN NEW.kind='PUBLISH' AND EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=NEW.entity_id AND u.source_version=NEW.source_version AND u.state IN ('PENDING','REVIEW')) BEGIN SELECT RAISE(ABORT,'pending undo prevents publication'); END;
CREATE TABLE IF NOT EXISTS continuous_pending_undo_apply_auth(request_id TEXT PRIMARY KEY REFERENCES continuous_pending_undo(request_id),audit_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_apply_auth_insert BEFORE INSERT ON continuous_pending_undo_apply_auth
WHEN NOT EXISTS(SELECT 1 FROM continuous_pending_undo u JOIN expense_events e ON e.expense_id=u.expense_id AND e.version=u.source_version AND e.status='CONFIRMED' AND e.line_user_id=u.line_user_id JOIN expense_audit_log a ON a.audit_id=NEW.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' AND a.actor_employee_id IS u.actor_employee_id AND a.branch_id IS u.branch_id AND json_extract(a.before_json,'$.version')=u.source_version AND json_extract(a.after_json,'$.status')='CANCELLED' JOIN continuous_publication_intents i ON i.transition_id=u.publication_transition_id AND i.entity_id=u.expense_id AND i.source_version=u.source_version AND i.kind='PUBLISH' AND i.state='VERIFIED' JOIN continuous_normal_notice_handoffs h ON h.spreadsheet_id=i.spreadsheet_id AND h.operation_token=i.claim_token AND h.expense_id=i.entity_id AND h.source_version=i.source_version AND h.projection='PUBLICATION' AND h.journal_entity=i.transition_id AND h.operation_kind='CONFIRM' JOIN continuous_review_notice_close n ON n.spreadsheet_id=h.spreadsheet_id AND n.operation_token=h.operation_token AND n.expense_id=h.expense_id AND n.source_version=h.source_version AND n.projection='PUBLICATION' AND n.journal_entity=h.journal_entity AND n.state='COMPLETE' WHERE u.request_id=NEW.request_id AND u.state='PENDING' AND NOT EXISTS(SELECT 1 FROM stable_workbook_claims c WHERE c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token))
BEGIN SELECT RAISE(ABORT,'pending undo authorization unverified'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_apply_auth_no_update BEFORE UPDATE ON continuous_pending_undo_apply_auth BEGIN SELECT RAISE(ABORT,'pending undo authorization immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_apply_auth_no_delete BEFORE DELETE ON continuous_pending_undo_apply_auth BEGIN SELECT RAISE(ABORT,'pending undo authorization retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_apply_auth_no_replace BEFORE INSERT ON continuous_pending_undo_apply_auth WHEN EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth WHERE request_id=NEW.request_id OR audit_id=NEW.audit_id) BEGIN SELECT RAISE(ABORT,'pending undo authorization collision'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_update BEFORE UPDATE ON expense_events WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=OLD.expense_id AND u.state IN ('PENDING','REVIEW') AND NOT (u.state='PENDING' AND NEW.status='CANCELLED' AND EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth t JOIN expense_audit_log a ON a.audit_id=t.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' WHERE t.request_id=u.request_id AND json_extract(a.before_json,'$.version')=OLD.version AND json_extract(a.after_json,'$.version')=NEW.version))) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_delete BEFORE DELETE ON expense_events WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=OLD.expense_id AND u.state IN ('PENDING','REVIEW')) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_document_items_insert BEFORE INSERT ON expense_document_items WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=NEW.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=NEW.expense_id AND u.state IN ('PENDING','REVIEW')) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_document_items_update BEFORE UPDATE ON expense_document_items WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=OLD.expense_id AND u.state IN ('PENDING','REVIEW')) OR EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=NEW.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=NEW.expense_id AND u.state IN ('PENDING','REVIEW')) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
