CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_documents_update BEFORE UPDATE ON expense_documents WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=OLD.expense_id AND u.state IN ('PENDING','REVIEW') AND NOT (u.state='PENDING' AND NEW.status='CANCELLED' AND OLD.status='CONFIRMED' AND EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth t JOIN expense_audit_log a ON a.audit_id=t.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' JOIN expense_events e ON e.expense_id=u.expense_id AND e.status='CANCELLED' AND e.version=json_extract(a.after_json,'$.version') WHERE t.request_id=u.request_id))) OR EXISTS(SELECT 1 FROM expense_document_links link WHERE link.document_id=OLD.document_id AND (EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=link.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=link.expense_id AND u.state IN ('PENDING','REVIEW') AND NOT (u.state='PENDING' AND NEW.status='CANCELLED' AND OLD.status='CONFIRMED' AND EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth t JOIN expense_audit_log a ON a.audit_id=t.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' JOIN expense_events e ON e.expense_id=u.expense_id AND e.status='CANCELLED' AND e.version=json_extract(a.after_json,'$.version') WHERE t.request_id=u.request_id))))) OR EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=NEW.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=NEW.expense_id AND u.state IN ('PENDING','REVIEW') AND NOT (u.state='PENDING' AND NEW.status='CANCELLED' AND OLD.status='CONFIRMED' AND EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth t JOIN expense_audit_log a ON a.audit_id=t.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' JOIN expense_events e ON e.expense_id=u.expense_id AND e.status='CANCELLED' AND e.version=json_extract(a.after_json,'$.version') WHERE t.request_id=u.request_id))) OR EXISTS(SELECT 1 FROM expense_document_links link WHERE link.document_id=NEW.document_id AND (EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=link.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=link.expense_id AND u.state IN ('PENDING','REVIEW') AND NOT (u.state='PENDING' AND NEW.status='CANCELLED' AND OLD.status='CONFIRMED' AND EXISTS(SELECT 1 FROM continuous_pending_undo_apply_auth t JOIN expense_audit_log a ON a.audit_id=t.audit_id AND a.expense_id=u.expense_id AND a.action='UNDO' JOIN expense_events e ON e.expense_id=u.expense_id AND e.status='CANCELLED' AND e.version=json_extract(a.after_json,'$.version') WHERE t.request_id=u.request_id))))) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_documents_delete BEFORE DELETE ON expense_documents WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=OLD.expense_id AND u.state IN ('PENDING','REVIEW')) OR EXISTS(SELECT 1 FROM expense_document_links link WHERE link.document_id=OLD.document_id AND (EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=link.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) OR EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=link.expense_id AND u.state IN ('PENDING','REVIEW')))) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
